using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

Console.WriteLine("Research Agent Starting...");

// Configure the chat client with tool support
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient innerClient = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient();

// Register tools
var searchTool = AIFunctionFactory.Create(ResearchTools.SearchWeb);
var addNoteTool = AIFunctionFactory.Create(ResearchTools.AddNote);
var readNotesTool = AIFunctionFactory.Create(ResearchTools.ReadNotes);

IChatClient agent = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools = [searchTool, addNoteTool, readNotesTool]
};

// Get the research topic
var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\nResearching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research the given topic thoroughly.

        Strategy:
        1. Search the web for relevant information using multiple queries.
        2. Take notes on key findings using the note-taking tool.
        3. After gathering enough information, read your notes and produce a final summary.

        Always take notes as you go so you don't lose important details.
        Provide a well-structured final summary with key points and sources.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
};

var response = await agent.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n========================\n");

// Show collected notes
var notes = ResearchTools.GetAllNotes();
if (notes.Count > 0)
{
    Console.WriteLine($"[Agent took {notes.Count} note(s) during research]");
}

return;

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input) ? "recent advances in quantum computing" : input;
}

/// <summary>Tools available to the research agent.</summary>
static class ResearchTools
{
    private static readonly List<string> _notes = [];
    private static readonly HttpClient _http = new();

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public static async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            var result = await _http.GetFromJsonAsync<JsonElement>(url);
            var snippets = new List<string>();

            // Extract abstract
            var abstractText = result.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                var source = result.GetProperty("AbstractSource").GetString();
                snippets.Add($"[{source}] {abstractText}");
            }

            // Extract related topics
            if (result.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                    {
                        var snippet = text.GetString();
                        if (!string.IsNullOrWhiteSpace(snippet))
                            snippets.Add(snippet);
                    }
                }
            }

            if (snippets.Count == 0)
                return $"No detailed results found for '{query}'. Try a different search query.";

            return string.Join("\n\n", snippets);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note. Use this to record important findings as you discover them.")]
    public static string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count} saved");
        return $"Note saved (total notes: {_notes.Count}).";
    }

    [Description("Read all saved research notes collected so far.")]
    public static string ReadNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  📖 Reading {_notes.Count} note(s)");
        return string.Join("\n---\n",
            _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }

    public static List<string> GetAllNotes() => _notes;
}

